/bin/bash -lc "python - <<'PY'
import csv, math
rows=list(csv.DictReader(open('/workspace/Swarm_2.csv')))
from collections import defaultdict
g=defaultdict(list)
for r in rows:
    g[(r['StrainNumber'],r['Ratio'])].append((float(r['Area']),float(r['Circularity'])))
means={k:(sum(a for a,c in v)/len(v), sum(c for a,c in v)/len(v)) for k,v in g.items()}
ref=means[('1','1:0')]
print('ref',ref)
for metric in ['raw_euclid','abs_pct_mean','scaled_range','scaled_sd']:
    # compute sd among mixed for scaling maybe
    mixed=[(k,v) for k,v in means.items() if k[0]=='287_98']
    if metric=='scaled_sd':
        aa=[v[0] for k,v in mixed]; cc=[v[1] for k,v in mixed]
        sa=(sum((x-(sum(aa)/len(aa)))**2 for x in aa)/(len(aa)-1))**.5
        sc=(sum((x-(sum(cc)/len(cc)))**2 for x in cc)/(len(cc)-1))**.5
        def d(v):
            return math.hypot((v[0]-ref[0])/sa,(v[1]-ref[1])/sc)
        best=min(mixed,key=lambda kv:d(kv[1]))
        print(metric,'sd',sa,sc,'best',best[0],best[1],'dist',d(best[1]))
    elif metric=='scaled_range':
        aa=[v[0] for k,v in mixed]; cc=[v[1] for k,v in mixed]
        sa=max(aa)-min(aa); sc=max(cc)-min(cc)
        def d(v):
            return math.hypot((v[0]-ref[0])/sa,(v[1]-ref[1])/sc)
        best=min(mixed,key=lambda kv:d(kv[1]))
        print(metric,'range',sa,sc,'best',best[0],best[1],'dist',d(best[1]))
    elif metric=='raw_euclid':
        def d(v):
            return math.hypot(v[0]-ref[0],v[1]-ref[1])
        best=min(mixed,key=lambda kv:d(kv[1]))
        print(metric,'best',best[0],best[1],'dist',d(best[1]))
    else:
        def d(v):
            return (abs(v[0]-ref[0])/ref[0] + abs(v[1]-ref[1])/ref[1])/2
        best=min(mixed,key=lambda kv:d(kv[1]))
        print(metric,'best',best[0],best[1],'dist',d(best[1]))
PY"

